mapper.select:
SELECT ir.inspection_route_id inspectionRouteId, ir.route_name routeName, ip.inspection_id inspectionId, ip.inspection_name inspectionName FROM inspection_route ir LEFT JOIN inspection_route_point_rel irpr ON irpr.inspection_route_id = ir.inspection_route_id LEFT JOIN inspection_point ip ON ip.inspection_id = irpr.inspection_id WHERE ir.status_cd = '0' AND irpr.status_cd = '0' AND ip.status_cd = '0'
AND ir.community_id = #{communityId}
AND ir.route_name LIKE concat('%',#{routeName},'%')
AND ip.inspection_name LIKE concat('%',#{inspectionName},'%')
ORDER BY ir.create_time DESC
limit #{page}, #{row}

select t.operate,t.inspection_route_id,t.inspection_route_id inspectionRouteId,t.seq,t.remark,t.community_id,t.community_id
communityId,t.b_id,t.b_id bId,t.route_name,t.route_name routeName
from business_inspection_route t
where 1 =1

    and t.operate= #{operate}


    and t.inspection_route_id= #{inspectionRouteId}


    and t.seq= #{seq}


    and t.remark= #{remark}


    and t.community_id= #{communityId}


    and t.b_id= #{bId}


    and t.route_name= #{routeName}

mapper.insert:
insert into inspection_route(
inspection_route_id,seq,remark,status_cd,community_id,b_id,route_name
) select
t.inspection_route_id,t.seq,t.remark,'0',t.community_id,t.b_id,t.route_name from
business_inspection_route t where 1=1
and t.operate= 'ADD'

    and t.inspection_route_id= #{inspectionRouteId}


    and t.seq= #{seq}


    and t.remark= #{remark}


    and t.community_id= #{communityId}


    and t.b_id= #{bId}


    and t.route_name= #{routeName}

